import urllib.parse
def inspect_service(request,namespace,name):
    base='/api/v1/namespaces/'+namespace+'/services/'+name
    code,service=request('GET',base)
    if code==403:raise PermissionError('Service access denied')
    if code!=200:raise RuntimeError('Service read failed')
    path='/apis/discovery.k8s.io/v1/namespaces/'+namespace+'/endpointslices?'+urllib.parse.urlencode({'labelSelector':'kubernetes.io/service-name='+name})
    code,slices=request('GET',path)
    if code==403:raise PermissionError('EndpointSlice access denied')
    if code!=200:raise RuntimeError('EndpointSlice read failed')
    ready=any(endpoint.get('conditions',{}).get('ready') is True for row in slices['items'] for endpoint in (row.get('endpoints') or []))
    mode='selector-controller' if service['spec'].get('selector') else 'external'
    return {'management':mode,'has_ready_endpoint':ready,'business_health':'not-tested'}
```

